// Command genkeys generates the demo keypairs and writes the embedded-key
// source files for both sides:
//
//	web/wasm/src/keys_gen.rs  -> Ed25519 signing seed + backend x25519 public key
//	cmd/server/keys_gen.go    -> Ed25519 verify key    + backend x25519 secret key
//
// Both generated files are git-ignored. Run this once before building.
//
// NOTE: shipping the Ed25519 signing key inside client-side WASM does NOT
// authenticate the submitter (the key is extractable). The real guarantee here
// is confidentiality: only the backend holds the x25519 secret, so only it can
// decrypt the sealed payload. See README threat model.
package main

import (
	"crypto/ed25519"
	"crypto/rand"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/crypto/curve25519"
)

func main() {
	root := "."
	if len(os.Args) > 1 {
		root = os.Args[1]
	}

	edPub, edPriv, err := ed25519.GenerateKey(rand.Reader)
	must(err)
	edSeed := edPriv.Seed()

	xSecret := make([]byte, 32)
	_, err = rand.Read(xSecret)
	must(err)
	xPub, err := curve25519.X25519(xSecret, curve25519.Basepoint)
	must(err)

	rs := fmt.Sprintf(`// @generated by cmd/genkeys — DO NOT EDIT, DO NOT COMMIT.
pub const ED25519_SEED: [u8; 32] = %s;
pub const SERVER_X25519_PUB: [u8; 32] = %s;
`, rustArr(edSeed), rustArr(xPub))

	gs := fmt.Sprintf(`// @generated by cmd/genkeys — DO NOT EDIT, DO NOT COMMIT.
package main

// ed25519Pub verifies signatures produced by the WASM module.
var ed25519Pub = []byte%s

// x25519Secret decrypts envelopes sealed by the WASM module.
var x25519Secret = []byte%s
`, goArr(edPub), goArr(xSecret))

	writeFile(filepath.Join(root, "web", "wasm", "src", "keys_gen.rs"), rs)
	writeFile(filepath.Join(root, "cmd", "server", "keys_gen.go"), gs)
	fmt.Println("generated keys_gen.rs and keys_gen.go")
}

func rustArr(b []byte) string {
	parts := make([]string, len(b))
	for i, v := range b {
		parts[i] = fmt.Sprintf("0x%02x", v)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func goArr(b []byte) string {
	parts := make([]string, len(b))
	for i, v := range b {
		parts[i] = fmt.Sprintf("0x%02x", v)
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

func writeFile(path, content string) {
	must(os.WriteFile(path, []byte(content), 0o644))
	fmt.Println("wrote", path)
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "genkeys:", err)
		os.Exit(1)
	}
}
